def stock_by_warehouse(items, warehouse_field):
    """按仓库统计库存。"""
    totals = {}
    current = None
    running = 0
    for item in items:
        warehouse = item[warehouse_field]
        if warehouse != current:
            current = warehouse
            running = 0
        running += item["qty"]
        totals[warehouse] = running
    return totals

verification_tests:
from target import stock_by_warehouse


def test_interrupted_warehouse_is_still_summed():
    items = [
        {"wh": "w1", "qty": 3},
        {"wh": "w2", "qty": 4},
        {"wh": "w1", "qty": 2},
    ]
    assert stock_by_warehouse(items, "wh") == {"w1": 5, "w2": 4}


def test_single_warehouse_total():
    items = [{"wh": "w1", "qty": 3}, {"wh": "w1", "qty": 4}]
    assert stock_by_warehouse(items, "wh") == {"w1": 7}


def test_empty_input_returns_empty_dict():
    assert stock_by_warehouse([], "wh") == {}
